const rows = $('Get last month\'s conversations').all();
const sqlStats = $('Get SQL Stats').first().json;

function maskPhone(phone) {
  if (!phone || phone.length < 6) return '***';
  return phone.slice(0, 4) + '***' + phone.slice(-3);
}

// Stats from SQL (accurate, uncapped)
const uniqueClients = Number(sqlStats.unique_clients) || 0;
const totalHuman = Number(sqlStats.total_human) || 0;
const totalAssistant = Number(sqlStats.total_assistant) || 0;
const totalMessages = Number(sqlStats.total_messages) || 0;
const avgMessagesPerUser = sqlStats.avg_messages_per_user || '0';
const avgHumanPerUser = sqlStats.avg_human_per_user || '0';
const avgAssistantPerUser = sqlStats.avg_assistant_per_user || '0';
const singleMessageUsers = Number(sqlStats.single_message_users) || 0;
const escalationCount = Number(sqlStats.escalation_users) || 0;
const botResolutionRate = uniqueClients > 0
  ? ((1 - escalationCount / uniqueClients) * 100).toFixed(1)
  : '0';
const dist1 = Number(sqlStats.dist_1msg) || 0;
const dist2to5 = Number(sqlStats.dist_2to5) || 0;
const dist5plus = Number(sqlStats.dist_5plus) || 0;

// Top users from SQL
let sqlTopUsers = [];
try {
  sqlTopUsers = typeof sqlStats.top_users_json === 'string'
    ? JSON.parse(sqlStats.top_users_json)
    : (sqlStats.top_users_json || []);
} catch(e) { sqlTopUsers = []; }

const topUsers = sqlTopUsers.map(r => ({
  phone_masked: maskPhone(r.phone_e164),
  total: Number(r.total),
  human: Number(r.human),
  assistant: Number(r.assistant)
}));

// Date and filename (computed once, used by both paths)
const now = new Date();
const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const roMonths = ['ianuarie','februarie','martie','aprilie','mai','iunie','iulie','august','septembrie','octombrie','noiembrie','decembrie'];
const roMonthName = roMonths[lastMonth.getMonth()];
const year = lastMonth.getFullYear();
const monthNameRo = `${roMonthName} ${year}`;
const fileName = `raport_lunar_${roMonthName}_${year}`;

const stats = {
  uniqueClients, totalMessages, totalHuman, totalAssistant,
  avgMessagesPerUser, avgHumanPerUser, avgAssistantPerUser,
  singleMessageUsers, escalationCount, botResolutionRate,
  dist1, dist2to5, dist5plus
};

// Parse messages
const parsed = rows.map(r => {
  let msg = r.json.message;
  if (typeof msg === 'string') {
    try { msg = JSON.parse(msg); } catch(e) { return null; }
  }
  return {
    phone_e164: r.json.phone_e164,
    type: msg.type === 'human' ? 'human' : 'assistant',
    content: msg.content || ''
  };
}).filter(Boolean);

// Group by phone, build transcripts
const sessions = {};
for (const m of parsed) {
  if (!sessions[m.phone_e164]) sessions[m.phone_e164] = [];
  sessions[m.phone_e164].push(m);
}

const allConversations = [];
for (const [phone, msgs] of Object.entries(sessions)) {
  const transcript = msgs
    .map(m => `${m.type === 'human' ? 'User' : 'Bot'}: ${m.content}`)
    .join('\n');
  allConversations.push(`--- ${maskPhone(phone)} (${msgs.length} msgs) ---\n${transcript}`);
}

// Empty month: no parseable conversations
if (allConversations.length === 0) {
  return [{
    json: {
      isEmptyMonth: true,
      monthNameRo, fileName, stats, topUsers,
      totalConversations: 0,
      totalChunks: 0,
      haikuRequestBody: null,
      chunkIndex: 0
    }
  }];
}

// Split oversized single-user conversations
const MAX_CONV_CHARS = 200000;
const safeConversations = [];
for (const conv of allConversations) {
  if (conv.length <= MAX_CONV_CHARS) {
    safeConversations.push(conv);
  } else {
    let remaining = conv;
    while (remaining.length > MAX_CONV_CHARS) {
      let splitIdx = remaining.lastIndexOf('\n', MAX_CONV_CHARS);
      if (splitIdx < MAX_CONV_CHARS / 2) splitIdx = MAX_CONV_CHARS;
      safeConversations.push(remaining.substring(0, splitIdx));
      remaining = remaining.substring(splitIdx);
    }
    if (remaining.trim().length > 0) safeConversations.push(remaining);
  }
}

// Chunk conversations for Haiku
const CHUNK_CHAR_LIMIT = 300000;
const chunks = [];
let currentChunk = '';
for (const conv of safeConversations) {
  if (currentChunk.length + conv.length + 2 > CHUNK_CHAR_LIMIT && currentChunk.length > 0) {
    chunks.push(currentChunk);
    currentChunk = '';
  }
  currentChunk += conv + '\n\n';
}
if (currentChunk.trim().length > 0) chunks.push(currentChunk);

const shared = {
  monthNameRo, fileName, stats, topUsers,
  totalConversations: allConversations.length,
  totalChunks: chunks.length
};

// Pre-build Haiku request bodies (avoids n8n expression injection from user messages)
const systemPrompt = 'Ești un analist de business. Analizezi conversații dintre clienți și un asistent WhatsApp pentru a înțelege nevoile, întrebările și problemele clienților. Returnează DOAR JSON valid, fără markdown code fences, fără text suplimentar. Toate textele în limba română.';

return chunks.map((chunk, i) => {
  const userMessage = `Analizează acest set de conversații (chunk ${i + 1} din ${chunks.length}) dintre clienții companiei Partner și asistentul WhatsApp.\n\nCONVERSAȚII:\n${chunk}\n\nConcentrează-te pe perspectiva business: ce vor clienții, ce probleme au, ce întreabă cel mai des.\n\nReturnează DOAR un JSON valid cu aceste câmpuri:\n{\n  "themes": [{"name": "subiectul/tema întrebării", "count": N, "example": "exemplu întrebare de la client"}],\n  "customer_problems": [{"problem": "problema clientului", "count": N, "resolved": true/false}],\n  "customer_needs": ["nevoie/cerere frecventă identificată"],\n  "escalation_requests": ["cerere explicită de a vorbi cu un om"],\n  "unanswered_questions": ["întrebare la care clientul nu a primit răspuns satisfăcător"]\n}`;

  const requestBody = {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 2000,
    system: systemPrompt,
    messages: [{ role: 'user', content: userMessage }]
  };

  return {
    json: {
      ...(i === 0 ? shared : {}),
      isEmptyMonth: false,
      chunkIndex: i,
      totalChunks: chunks.length,
      haikuRequestBody: JSON.stringify(requestBody)
    }
  };
});

// Check if we came from the empty-month path or the full-analysis path
// Try to read from Skip to Report first (empty month), fall back to Merge
let mergeData, isEmpty;
try {
  mergeData = $('Skip to Report').first().json;
  isEmpty = true;
} catch(e) {
  mergeData = $('Merge Chunk Results').first().json;
  isEmpty = mergeData && mergeData.emptyMonth;
}

const shared = isEmpty ? mergeData.shared : mergeData.shared;
const s = shared.stats;
const genDate = new Date().toLocaleDateString('ro-RO', { year: 'numeric', month: 'long', day: 'numeric' });

if (isEmpty) {
  const html = `<!DOCTYPE html>
<html lang="ro"><head><meta charset="UTF-8"><title>Raport Lunar Suport — ${shared.monthNameRo}</title>
<style>body{font-family:Arial,sans-serif;margin:0;padding:0;background:#fff;color:#333;line-height:1.6}.header{background:#2c3e50;color:#fff;padding:30px 40px}.header h1{margin:0 0 5px 0;font-size:24px}.header p{margin:0;opacity:.85;font-size:14px}.content{padding:30px 40px;max-width:900px}h2{color:#2c3e50;border-bottom:2px solid #3498db;padding-bottom:6px;margin-top:32px;font-size:18px}</style>
</head><body>
<div class="header"><h1>Raport Lunar Suport — ${shared.monthNameRo}</h1><p>Generat: ${genDate}</p></div>
<div class="content"><h2>Fără date</h2><p>Nu au fost înregistrate conversații în luna ${shared.monthNameRo}.</p></div>
</body></html>`;

  const fileName = shared.fileName;
  const folderId = '1mIBnp7jJBf0AIAejO33lcQutWBfMWqmn';
  const boundary = '----n8nBoundary' + Date.now();
  const CRLF = '\r\n';
  const metadata = JSON.stringify({ name: fileName, mimeType: 'application/vnd.google-apps.document', parents: [folderId] });
  const bodyStr = `--${boundary}${CRLF}Content-Type: application/json; charset=UTF-8${CRLF}${CRLF}${metadata}${CRLF}--${boundary}${CRLF}Content-Type: text/html; charset=UTF-8${CRLF}${CRLF}${html}${CRLF}--${boundary}--`;
  const bodyBuffer = Buffer.from(bodyStr, 'utf-8');
  const contentType = `multipart/related; boundary=${boundary}`;
  return [{ json: { fileName, contentType }, binary: { data: await this.helpers.prepareBinaryData(bodyBuffer, 'upload.bin', contentType) } }];
}

// === Normal path: parse Sonnet response ===
const sonnetResp = $('Sonnet: Final Report').first().json;

if (sonnetResp.error) {
  throw new Error('Sonnet API error: ' + (sonnetResp.error.message || JSON.stringify(sonnetResp.error)));
}

let rawText = '';
if (Array.isArray(sonnetResp.content)) {
  rawText = sonnetResp.content.map(b => b.text || '').join('');
} else {
  rawText = sonnetResp.text || sonnetResp.output || '';
}
rawText = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

let analysis;
try {
  analysis = JSON.parse(rawText);
} catch(e) {
  throw new Error('Sonnet did not return valid JSON: ' + rawText.substring(0, 500));
}

const meta = shared;

// Table builders
const topUserRows = (shared.topUsers || []).map((u, i) =>
  `<tr class="${i % 2 === 0 ? 'even' : 'odd'}">
    <td>${i + 1}</td><td>${u.phone_masked}</td><td>${u.total}</td><td>${u.human}</td><td>${u.assistant}</td>
  </tr>`
).join('');

const questionRows = (analysis.top_questions || []).map((q, i) =>
  `<tr class="${i % 2 === 0 ? 'even' : 'odd'}">
    <td>${q.rank}</td><td>${q.theme}</td><td>${q.estimated_pct}</td><td>${q.example}</td>
  </tr>`
).join('');

const issueRows = (analysis.top_issues || []).map((q, i) =>
  `<tr class="${i % 2 === 0 ? 'even' : 'odd'}">
    <td>${i + 1}</td><td>${q.issue}</td><td>${q.estimated_pct}</td><td>${q.resolved ? 'Da' : 'Nu'}</td>
  </tr>`
).join('');

const recsHtml = (analysis.recommendations || []).map(r => `<li>${r}</li>`).join('');

function paragraphs(text) {
  if (!text) return '<p>—</p>';
  return text.split('\n').filter(Boolean).map(p => `<p>${p}</p>`).join('');
}

