const fileName = shared.fileName;
const folderId = '1mIBnp7jJBf0AIAejO33lcQutWBfMWqmn';
const boundary = '----n8nBoundary' + Date.now();
const CRLF = '\r\n';

const metadata = JSON.stringify({
  name: fileName,
  mimeType: 'application/vnd.google-apps.document',
  parents: [folderId]
});

const bodyStr =
  `--${boundary}${CRLF}` +
  `Content-Type: application/json; charset=UTF-8${CRLF}` +
  `${CRLF}` +
  `${metadata}${CRLF}` +
  `--${boundary}${CRLF}` +
  `Content-Type: text/html; charset=UTF-8${CRLF}` +
  `${CRLF}` +
  `${html}${CRLF}` +
  `--${boundary}--`;

const bodyBuffer = Buffer.from(bodyStr, 'utf-8');
const contentType = `multipart/related; boundary=${boundary}`;

return [{
  json: { fileName, contentType },
  binary: {
    data: await this.helpers.prepareBinaryData(bodyBuffer, 'upload.bin', contentType)
  }
}];

const firstItem = $('Compute Stats & Prepare Data').first().json;

const shared = {
  monthNameRo: firstItem.monthNameRo,
  fileName: firstItem.fileName,
  stats: firstItem.stats,
  topUsers: firstItem.topUsers,
  totalConversations: firstItem.totalConversations,
  totalChunks: firstItem.totalChunks
};

const items = $('Haiku: Analyze Chunk').all();
const chunkResults = [];

for (const item of items) {
  try {
    const resp = item.json;
    if (resp.error) {
      chunkResults.push({
        themes: [], issues: [],
        customer_needs: ['Eroare API: ' + (resp.error.message || JSON.stringify(resp.error))],
        escalation_requests: [], unanswered_questions: []
      });
      continue;
    }

    const content = resp.content;
    let text = '';
    if (Array.isArray(content)) {
      text = content.map(b => b.text || '').join('');
    } else if (typeof content === 'string') {
      text = content;
    }
    const cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
    chunkResults.push(JSON.parse(cleaned));
  } catch(e) {
    chunkResults.push({
      themes: [], issues: [],
      customer_needs: ['Eroare procesare chunk: ' + e.message],
      escalation_requests: [], unanswered_questions: []
    });
  }
}

const s = shared.stats;

const mergePrompt = `Sintetizează următoarele analize ale conversațiilor cu clienții companiei "Partner" din ${shared.monthNameRo}. Acest raport este destinat proprietarului afacerii și trebuie să ofere o imagine clară a nevoilor și problemelor clienților.

STATISTICI GLOBALE:
- Clienți unici care au contactat suportul: ${s.uniqueClients}
- Total mesaje schimbate: ${s.totalMessages} (clienți: ${s.totalHuman}, asistent: ${s.totalAssistant})
- Clienți care au cerut să vorbească cu un operator: ${s.escalationCount}
- Rata de rezolvare automată: ${s.botResolutionRate}%
- Angajament: ${s.dist1} clienți cu o singură întrebare, ${s.dist2to5} cu 2-5 mesaje, ${s.dist5plus} cu peste 5 mesaje
- Total conversații analizate: ${shared.totalConversations}

ANALIZE DIN ${shared.totalChunks} SEGMENTE:
${JSON.stringify(chunkResults, null, 1)}

Sintetizează într-un singur JSON cu exact aceste câmpuri (TOATE ÎN LIMBA ROMÂNĂ):
{
  "executive_summary": "3-4 propoziții rezumat pentru proprietarul afacerii: câți clienți au contactat suportul, ce au cerut cel mai des, care sunt problemele principale",
  "top_questions": [
    {"rank": 1, "theme": "subiectul", "estimated_pct": "X%", "example": "exemplu întrebare de la client"},
    ...5 total, agregate din toate segmentele
  ],
  "top_issues": [
    {"issue": "problema clientului", "estimated_pct": "X%", "resolved": true/false},
    ...5 total — problemele cele mai frecvente ale CLIENȚILOR, nu ale botului
  ],
  "customer_insights": "2-3 paragrafe: ce tipare se observă în nevoile clienților, ce informații lipsesc frecvent, ce frustrări au clienții, ce funcționează bine",
  "engagement_analysis": "1-2 paragrafe: ce spune distribuția angajamentului despre comportamentul clienților (clienți cu o singură întrebare vs conversații lungi)",
  "recommendations": ["rec 1", "rec 2", ...3-5 recomandări acționabile pentru îmbunătățirea serviciilor și a satisfacției clienților]
}`;

// Pre-build Sonnet request body (avoids n8n expression injection)
const sonnetRequestBody = JSON.stringify({
  model: 'claude-sonnet-4-6',
  max_tokens: 3000,
  system: 'Ești un analist senior de business. Sintetizezi date despre interacțiunile clienților într-un raport clar și acționabil pentru proprietarul afacerii. Concentrează-te pe nevoile clienților, nu pe performanța tehnică a botului. Returnează DOAR JSON valid, fără markdown code fences. Totul în limba română.',
  messages: [{ role: 'user', content: mergePrompt }]
});

return [{
