const d = $('Compute Stats & Prepare Data').first().json;
return [{
  json: {
    mergePrompt: null,
    shared: {
      monthNameRo: d.monthNameRo,
      fileName: d.fileName,
      stats: d.stats,
      topUsers: d.topUsers || [],
      totalConversations: 0,
      totalChunks: 0
    },
    emptyMonth: true
  }
}];

const doc = $input.first().json;
const docId = doc.documentId;
const content = doc.body.content || [];
const PLACEHOLDER = '%%%PAGEBREAK%%%';

// Find all paragraph elements containing the placeholder
const positions = [];
for (const element of content) {
  if (element.paragraph && element.paragraph.elements) {
    for (const el of element.paragraph.elements) {
      if (el.textRun && el.textRun.content && el.textRun.content.includes(PLACEHOLDER)) {
        positions.push({
          start: element.startIndex,
          end: element.endIndex
        });
      }
    }
  }
}

if (positions.length === 0) {
  return [{ json: { docId, requests: [], pageBreaksInserted: 0 } }];
}

// Build batchUpdate requests in reverse order (so indices don't shift)
positions.sort((a, b) => b.start - a.start);

const requests = [];
for (const pos of positions) {
  // First delete the placeholder paragraph
  requests.push({
    deleteContentRange: {
      range: { startIndex: pos.start, endIndex: pos.end }
    }
  });
  // Then insert a page break at that position
  requests.push({
    insertPageBreak: {
      location: { index: pos.start }
    }
  });
}

return [{ json: { docId, requestBody: JSON.stringify({ requests }), pageBreaksInserted: positions.length } }];
